def get_task_comments(self, patient_id, task_id):
        """
        invokes TouchWorksMagicConstants.ACTION_GET_ENCOUNTER_LIST_FOR_PATIENT action
        :return: JSON response
        """
        url = self.url + TouchWorksMagicConstants.ACTION_GET_TASK_COMMENTS
        headers = {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + self.token
        }
        payload = {
            'patientId': patient_id,
            'taskId': task_id
        }
        return self.get_json(url, headers, payload)

